-- 0025_research_sources_studies_runs.sql
-- Phase 2 research persistence: sources, studies, research runs.
-- Imports validated rows from published.json only (not raw connector cache).
-- Does not store claims, evidence A–F, regulatory_records, or community reports.
-- Does not alter shop tables. Lexicon still reads catalog.ts + published.json.

create table public.research_runs (
  id uuid primary key default gen_random_uuid(),
  run_type text not null
    check (run_type in ('historical_import', 'migration_import', 'live')),
  connector text not null,
  query text,
  batch_label text,
  status text not null
    check (status in ('running', 'completed', 'failed')),
  started_at timestamptz,
  completed_at timestamptz,
  sources_found integer,
  sources_accepted integer,
  sources_rejected integer,
  studies_found integer,
  studies_accepted integer,
  errors text,
  operator_note text,
  created_at timestamptz not null default now()
);

comment on table public.research_runs is
  'Traceable research execution. historical_import rows are not live connector logs.';

create index research_runs_connector_idx on public.research_runs (connector);
create index research_runs_started_at_idx on public.research_runs (started_at);

create table public.sources (
  id uuid primary key default gen_random_uuid(),
  source_type text not null
    check (source_type in (
      'fda', 'ema', 'bfarm', 'mhra',
      'clinical_trial', 'pubmed', 'journal',
      'systematic_review', 'review', 'meta_analysis',
      'manufacturer', 'literature', 'scientific',
      'regulatory', 'other'
    )),
  title text not null check (char_length(trim(title)) >= 1),
  publisher text,
  authors text,
  publication_date text,
  access_date text,
  url text not null,
  doi text,
  pmid text,
  nct_id text,
  abstract text,
  external_id text,
  source_quality smallint check (source_quality is null or source_quality between 1 and 5),
  status text not null default 'active'
    check (status in ('active', 'superseded', 'unavailable', 'rejected')),
  legacy_ids text[] not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint sources_pmid_digits check (pmid is null or pmid ~ '^[0-9]+$'),
  constraint sources_nct_format check (nct_id is null or nct_id ~ '^NCT[0-9]{8}$')
);

comment on table public.sources is
  'Normalized scientific source. status is record lifecycle, not evidence A–F. Community types are not stored here.';
comment on column public.sources.doi is 'Normalized DOI (lowercase, no doi: or doi.org prefix).';
comment on column public.sources.pmid is 'Numeric PMID digits only.';
comment on column public.sources.nct_id is 'Uppercase NCT########.';

create unique index sources_pmid_key on public.sources (pmid) where pmid is not null;
create unique index sources_doi_key on public.sources (doi) where doi is not null;
create unique index sources_nct_id_key on public.sources (nct_id) where nct_id is not null;
create index sources_source_type_idx on public.sources (source_type);
create index sources_publication_date_idx on public.sources (publication_date);
create index sources_status_idx on public.sources (status);

create trigger sources_set_updated_at
  before update on public.sources
  for each row execute function public.set_updated_at();

create table public.source_substances (
  id uuid primary key default gen_random_uuid(),
  source_id uuid not null references public.sources (id) on delete restrict,
  substance_id uuid not null references public.substances (id) on delete restrict,
  legacy_source_id text not null,
  created_at timestamptz not null default now(),
  constraint source_substances_pair unique (source_id, substance_id)
);

comment on table public.source_substances is
  'Source ↔ substance. ON DELETE RESTRICT so identity deletion cannot drop scientific history.';

create index source_substances_substance_id_idx on public.source_substances (substance_id);

create table public.studies (
  id uuid primary key default gen_random_uuid(),
  nct_id text not null,
  title text not null check (char_length(trim(title)) >= 1),
  sponsor text,
  phase text,
  status text,
  enrollment integer,
  start_date text,
  completion_date text,
  last_updated text,
  has_results boolean not null default false,
  source_url text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint studies_nct_format check (nct_id ~ '^NCT[0-9]{8}$')
);

comment on table public.studies is
  'ClinicalTrials.gov study. Unique NCT. Intervention/outcomes omitted until sourced.';

create unique index studies_nct_id_key on public.studies (nct_id);
create index studies_status_idx on public.studies (status);
create index studies_phase_idx on public.studies (phase);

create trigger studies_set_updated_at
  before update on public.studies
  for each row execute function public.set_updated_at();

create table public.study_substances (
  id uuid primary key default gen_random_uuid(),
  study_id uuid not null references public.studies (id) on delete restrict,
  substance_id uuid not null references public.substances (id) on delete restrict,
  created_at timestamptz not null default now(),
  constraint study_substances_pair unique (study_id, substance_id)
);

create index study_substances_substance_id_idx on public.study_substances (substance_id);

create table public.study_sources (
  id uuid primary key default gen_random_uuid(),
  study_id uuid not null references public.studies (id) on delete restrict,
  source_id uuid not null references public.sources (id) on delete restrict,
  created_at timestamptz not null default now(),
  constraint study_sources_pair unique (study_id, source_id)
);

create index study_sources_source_id_idx on public.study_sources (source_id);

create table public.research_run_sources (
  id uuid primary key default gen_random_uuid(),
  research_run_id uuid not null references public.research_runs (id) on delete restrict,
  source_id uuid not null references public.sources (id) on delete restrict,
  discovered_at timestamptz,
  accepted boolean not null default true,
  rejection_reason text,
  created_at timestamptz not null default now(),
  constraint research_run_sources_pair unique (research_run_id, source_id)
);

create index research_run_sources_source_id_idx on public.research_run_sources (source_id);

alter table public.research_runs enable row level security;
alter table public.research_run_sources enable row level security;
alter table public.sources enable row level security;
alter table public.source_substances enable row level security;
alter table public.studies enable row level security;
alter table public.study_substances enable row level security;
alter table public.study_sources enable row level security;

